// These are additional cases which the official break tests don't cover:
static constexpr GraphemeBreakTest s_graphemeBreakTestsExtra[] = {
    { L"multiple combining marks", L"a\u0363", L"e\u0364\u0364", L"i\u0365" },
    { L"multiple US flag regional indicators", L"\U0001F1FA\U0001F1F8", L"\U0001F1FA\U0001F1F8" },
};

static constexpr std::span<const GraphemeBreakTest> s_graphemeBreakTestsAll[] = {
    s_graphemeBreakTests,
    s_graphemeBreakTestsExtra,
};

class CodepointWidthDetectorTests
{
    TEST_CLASS(CodepointWidthDetectorTests);

    TEST_METHOD(GraphemeBreakTest)
    {
        WEX::TestExecution::DisableVerifyExceptions disableVerifyExceptions{};
        WEX::TestExecution::SetVerifyOutput verifyOutputScope{ WEX::TestExecution::VerifyOutputSettings::LogOnlyFailures };

        auto& cwd = CodepointWidthDetector::Singleton();
        std::vector<std::wstring_view> expected;
        std::vector<std::wstring_view> actual;
        std::wstring text;

        for (const auto& tests : s_graphemeBreakTestsAll)
        {
            for (const auto& test : tests)
            {
                expected.clear();
                for (const auto g : test.graphemes)
                {
                    if (!g)
                    {
                        break;
                    }
                    expected.emplace_back(g);
                }

                text.clear();
                for (const auto& g : expected)
                {
                    text.append(g);
                }

                actual.clear();
                for (GraphemeState state;;)
                {
                    const auto ok = cwd.GraphemeNext(state, text);
                    actual.emplace_back(state.beg, state.len);
                    if (!ok)
                    {
                        break;
                    }
                }
                VERIFY_ARE_EQUAL(expected, actual, test.comment);

                actual.clear();
                for (GraphemeState state;;)
                {
                    const auto ok = cwd.GraphemePrev(state, text);
                    actual.emplace_back(state.beg, state.len);
                    if (!ok)
                    {
                        break;
                    }
                }
                std::reverse(actual.begin(), actual.end());
                VERIFY_ARE_EQUAL(expected, actual, test.comment);
            }
        }
    }

    TEST_METHOD(BasicGraphemes)
    {
        static constexpr std::wstring_view text{ L"a\u0363e\u0364\u0364i\u0365" };

        auto& cwd = CodepointWidthDetector::Singleton();

        const std::vector<size_t> expectedAdvances{ 2, 3, 2 };
        const std::vector<int> expectedWidths{ 1, 1, 1 };
        std::vector<size_t> actualAdvances;
        std::vector<int> actualWidths;

        for (GraphemeState state;;)
        {
            const auto ok = cwd.GraphemeNext(state, text);
            actualAdvances.emplace_back(state.len);
            actualWidths.emplace_back(state.width);
            if (!ok)
            {
                break;
            }
        }

        VERIFY_ARE_EQUAL(expectedAdvances, actualAdvances);
        VERIFY_ARE_EQUAL(expectedWidths, actualWidths);

        actualAdvances.clear();
        actualWidths.clear();

        for (GraphemeState state;;)
        {
            const auto ok = cwd.GraphemePrev(state, text);
            actualAdvances.emplace_back(state.len);
            actualWidths.emplace_back(state.width);
            if (!ok)
            {
                break;
            }
        }

        std::reverse(actualAdvances.begin(), actualAdvances.end());
        std::reverse(actualWidths.begin(), actualWidths.end());

        VERIFY_ARE_EQUAL(expectedAdvances, actualAdvances);
        VERIFY_ARE_EQUAL(expectedWidths, actualWidths);
    }

    TEST_METHOD(ChunkedText)
    {
        struct Test
        {
            TextMeasurementMode mode;
            std::vector<int> advancesNext;
            std::vector<int> widthsNext;
            std::vector<int> advancesPrev;
            std::vector<int> widthsPrev;
        };
        const std::array tests{
            Test{
                .mode = TextMeasurementMode::Graphemes,
                .advancesNext = { 3, 3, 0, 1 },
                .widthsNext = { 2, 2, 2, 1 },
                .advancesPrev = { 1, 0, 3, 3 },
                .widthsPrev = { 1, 1, 2, 2 },

            },
            Test{
                .mode = TextMeasurementMode::Wcswidth,
                .advancesNext = { 3, 1, 2, 0, 1 },
                .widthsNext = { 1, 1, 2, 2, 1 },
                .advancesPrev = { 1, 0, 2, 1, 3 },
                .widthsPrev = { 1, 1, 2, 0, 1 },
            },
            Test{
                .mode = TextMeasurementMode::Console,
                .advancesNext = { 2, 1, 0, 1, 2, 0, 1 },
                .widthsNext = { 1, 0, 0, 0, 2, 2, 1 },
                .advancesPrev = { 1, 0, 2, 1, 0, 1, 2 },
                .widthsPrev = { 1, 1, 2, 0, 0, 0, 1 },
            },
        };

        // That's a fully qualified rainbow flag followed by a single "a" character.
        static constexpr std::array chunks{
            std::wstring_view{ L"\U0001F3F3\uFE0F" },
            std::wstring_view{ L"\u200D\U0001F308" },
            std::wstring_view{ L"a" },
        };

        CodepointWidthDetector cwd;
        GraphemeState state;
        std::vector<int> actualAdvances;
        std::vector<int> actualWidths;

        for (const auto& test : tests)
        {
            cwd.Reset(test.mode);

            state = {};
            actualAdvances.clear();
            actualWidths.clear();

            for (int i = 0; i < 3; i++)
            {
                bool ok;
                do
                {
                    ok = cwd.GraphemeNext(state, chunks[i]);
                    actualAdvances.emplace_back(state.len);
                    actualWidths.emplace_back(state.width);
                } while (ok);
            }

            VERIFY_ARE_EQUAL(test.advancesNext, actualAdvances);
            VERIFY_ARE_EQUAL(test.widthsNext, actualWidths);

            state = {};
            actualAdvances.clear();
            actualWidths.clear();

            for (int i = 2; i >= 0; i--)
            {
                bool ok;
                do
                {
                    ok = cwd.GraphemePrev(state, chunks[i]);
                    actualAdvances.emplace_back(state.len);
                    actualWidths.emplace_back(state.width);
                } while (ok);
            }

            VERIFY_ARE_EQUAL(test.advancesPrev, actualAdvances);
            VERIFY_ARE_EQUAL(test.widthsPrev, actualWidths);
        }
    }

    TEST_METHOD(AmbiguousWidthPolicy)
    {
        const auto measureWidth = [](CodepointWidthDetector& cwd, const std::wstring_view text) {
            GraphemeState state;
            cwd.GraphemeNext(state, text);
            return state.width;
        };

        CodepointWidthDetector cwd;

        for (const auto mode : { TextMeasurementMode::Graphemes, TextMeasurementMode::Wcswidth })
        {
            cwd.Reset(mode);
            cwd.SetAmbiguousWidth(1);
            VERIFY_ARE_EQUAL(1, measureWidth(cwd, L"→"));
            cwd.SetAmbiguousWidth(2);
            VERIFY_ARE_EQUAL(2, measureWidth(cwd, L"→"));
        }
    }

    // Measures a single grapheme cluster in Graphemes mode by calling GraphemeNext/Prev end-to-end
    // and returns (totalWidth, totalLen). Uses a fresh detector per call so state is never leaked.
    static std::pair<int, int> MeasureGraphemesForward(std::wstring_view text)
    {
        CodepointWidthDetector cwd;
        cwd.Reset(TextMeasurementMode::Graphemes);
        GraphemeState state;
        int totalWidth = 0;
        int totalLen = 0;
        for (;;)
        {
            const auto ok = cwd.GraphemeNext(state, text);
            totalWidth = state.width; // single cluster under test → last observed width
            totalLen += state.len;
            if (!ok)
            {
                break;
            }
        }
        return { totalWidth, totalLen };
    }

    static std::pair<int, int> MeasureGraphemesReverse(std::wstring_view text)
    {
        CodepointWidthDetector cwd;
        cwd.Reset(TextMeasurementMode::Graphemes);
        GraphemeState state;
        int totalWidth = 0;
        int totalLen = 0;
        for (;;)
        {
            const auto ok = cwd.GraphemePrev(state, text);
            totalWidth = state.width;
            totalLen += state.len;
            if (!ok)
            {
                break;
            }
        }
        return { totalWidth, totalLen };
    }

    static int MeasureWcswidth(std::wstring_view text)
    {
        CodepointWidthDetector cwd;
        cwd.Reset(TextMeasurementMode::Wcswidth);
        GraphemeState state;
        int total = 0;
        for (;;)
        {
            const auto ok = cwd.GraphemeNext(state, text);
            total += state.width;
            if (!ok)
            {
                break;
            }
        }
        return total;
    }

    TEST_METHOD(VS15NarrowsEmojiPresentationBase)
    {
        // U+231A WATCH has Emoji_Presentation=Yes, east-asian "W" (intrinsically wide).
        // VS15 narrows it to 1 cell; VS16 keeps it wide.
        const auto [w15, l15] = MeasureGraphemesForward(L"\u231A\uFE0E");
        VERIFY_ARE_EQUAL(1, w15);
        VERIFY_ARE_EQUAL(2, l15);

        const auto [w16, l16] = MeasureGraphemesForward(L"\u231A\uFE0F");
        VERIFY_ARE_EQUAL(2, w16);
        VERIFY_ARE_EQUAL(2, l16);

        // U+2764 HEAVY BLACK HEART: Emoji=Y, Emoji_Presentation=No, east-asian "N".
        // Default presentation is text (width 1). VS15 is a no-op. VS16 promotes to wide.
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\u2764\uFE0E").first);
        VERIFY_ARE_EQUAL(2, MeasureGraphemesForward(L"\u2764\uFE0F").first);

        // Additional spot checks: both default-emoji-presentation (U+1F5E1 DAGGER KNIFE)
        // and default-text (U+2600 BLACK SUN WITH RAYS) collapse to <=1 under FE0E.
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\u2600\uFE0E").first); // default text
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\u26A0\uFE0E").first); // default text
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\u2615\uFE0E").first); // Hot Beverage, EPres=Y
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\U0001F5E1\uFE0E").first); // dagger, default text
    }

    TEST_METHOD(VS15DoesNotNarrowCJKIdeograph)
    {
        // U+4E00 CJK UNIFIED IDEOGRAPH-ONE is Emoji=No, east-asian "W".
        // VS15 must NOT narrow it; it remains wide (2 cells).
        VERIFY_ARE_EQUAL(2, MeasureGraphemesForward(L"\u4E00\uFE0E").first);
        VERIFY_ARE_EQUAL(2, MeasureGraphemesReverse(L"\u4E00\uFE0E").first);
    }

    TEST_METHOD(VS15NoOpOnAsciiBase)
    {
        // VS15 after a non-emoji narrow base is a no-op; width stays 1.
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"A\uFE0E").first);
        VERIFY_ARE_EQUAL(1, MeasureGraphemesReverse(L"A\uFE0E").first);
    }

    TEST_METHOD(VS15ForwardReverseParity)
    {
        struct Case
        {
            std::wstring_view input;
            int expectedWidth;
        };
        const std::array cases{
            Case{ L"\u231A\uFE0E", 1 },          // watch + VS15 = narrow
            Case{ L"\u231A\uFE0F", 2 },          // watch + VS16 = wide
            Case{ L"\u2764\uFE0E", 1 },          // heart + VS15 = narrow
            Case{ L"\u2764\uFE0F", 2 },          // heart + VS16 = wide
            Case{ L"\u4E00\uFE0E", 2 },          // CJK + VS15 = still wide
            Case{ L"A\uFE0E", 1 },               // ASCII + VS15 = narrow (no-op)
            Case{ L"\u2139\uFE0E", 1 },          // information source + VS15
        };
        for (const auto& c : cases)
        {
            const auto fwd = MeasureGraphemesForward(c.input);
            const auto rev = MeasureGraphemesReverse(c.input);
            VERIFY_ARE_EQUAL(c.expectedWidth, fwd.first, WEX::Common::String().Format(L"fwd width for case %d", static_cast<int>(c.input[0])));
            VERIFY_ARE_EQUAL(c.expectedWidth, rev.first, WEX::Common::String().Format(L"rev width for case %d", static_cast<int>(c.input[0])));
            VERIFY_ARE_EQUAL(fwd.second, rev.second);
        }
    }

    TEST_METHOD(VS15LastSelectorWins)
    {
        // base + FE0F + FE0E: VS15 is last → narrow.
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\u2764\uFE0F\uFE0E").first);
        VERIFY_ARE_EQUAL(1, MeasureGraphemesReverse(L"\u2764\uFE0F\uFE0E").first);
        // base + FE0E + FE0F: VS16 is last → wide.
        VERIFY_ARE_EQUAL(2, MeasureGraphemesForward(L"\u2764\uFE0E\uFE0F").first);
        VERIFY_ARE_EQUAL(2, MeasureGraphemesReverse(L"\u2764\uFE0E\uFE0F").first);
        // Same precedence for an intrinsically-wide Emoji_Presentation base (⌚).
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\u231A\uFE0F\uFE0E").first);
        VERIFY_ARE_EQUAL(1, MeasureGraphemesReverse(L"\u231A\uFE0F\uFE0E").first);
        VERIFY_ARE_EQUAL(2, MeasureGraphemesForward(L"\u231A\uFE0E\uFE0F").first);
        VERIFY_ARE_EQUAL(2, MeasureGraphemesReverse(L"\u231A\uFE0E\uFE0F").first);
    }

    TEST_METHOD(VS15WcswidthModeIsNoOp)
    {
        // Mirroring VS16 scoping (only forwards, only Graphemes mode), VS15 must not affect
        // Wcswidth. U+231A alone is wide in Wcswidth (east-asian "W") and FE0E contributes 0.
        // The total width must be identical before and after appending FE0E.
        const auto baseline = MeasureWcswidth(L"\u231A");
        const auto withVS15 = MeasureWcswidth(L"\u231A\uFE0E");
        VERIFY_ARE_EQUAL(baseline, withVS15);
    }

    TEST_METHOD(VS15OverridesAmbiguousWide)
    {
        // U+2139 INFORMATION SOURCE is east-asian Ambiguous, Emoji_Presentation=Yes.
        // With AmbiguousWidth=2 the base would otherwise widen to 2; VS15 must still narrow to 1.
        CodepointWidthDetector cwd;
        cwd.Reset(TextMeasurementMode::Graphemes);
        cwd.SetAmbiguousWidth(2);
        GraphemeState state;
        cwd.GraphemeNext(state, L"\u2139\uFE0E");
        VERIFY_ARE_EQUAL(1, state.width);
    }

    TEST_METHOD(VS15ExistingFE0FUnchanged)
    {
        // Regression guard: pre-existing FE0F behavior must be byte-identical.
        // U+2764 + FE0F yields width 2; plain U+2764 is narrow (1).
        VERIFY_ARE_EQUAL(1, MeasureGraphemesForward(L"\u2764").first);
        VERIFY_ARE_EQUAL(2, MeasureGraphemesForward(L"\u2764\uFE0F").first);
        VERIFY_ARE_EQUAL(2, MeasureGraphemesReverse(L"\u2764\uFE0F").first);
        // Rainbow flag still assembles correctly (VS16-qualified base + ZWJ + rainbow).
        VERIFY_ARE_EQUAL(2, MeasureGraphemesForward(L"\U0001F3F3\uFE0F\u200D\U0001F308").first);
    }

    TEST_METHOD(VS15LoneSelectorWidthSane)
    {
        // FE0E alone must never produce a negative width; len must be non-zero.
        const auto [w, l] = MeasureGraphemesForward(L"\uFE0E");
        VERIFY_IS_GREATER_THAN_OR_EQUAL(w, 0);
        VERIFY_IS_LESS_THAN_OR_EQUAL(w, 2);
        VERIFY_IS_GREATER_THAN(l, 0);

        // Combining acute accent + FE0E must not underflow either.
        const auto [w2, l2] = MeasureGraphemesForward(L"\u0301\uFE0E");
        VERIFY_IS_GREATER_THAN_OR_EQUAL(w2, 0);
        VERIFY_IS_LESS_THAN_OR_EQUAL(w2, 2);
        VERIFY_IS_GREATER_THAN(l2, 0);
    }

    TEST_METHOD(VS15ChunkedAcrossBoundary)
    {
        // VS15 must work when the base and the selector arrive in separate chunks
        // (mirrors the rainbow flag ChunkedText pattern above).
        static constexpr std::array chunks{
            std::wstring_view{ L"\u231A" },
            std::wstring_view{ L"\uFE0E" },
        };

        CodepointWidthDetector cwd;
        cwd.Reset(TextMeasurementMode::Graphemes);
        GraphemeState state;

        std::vector<int> widths;
        for (const auto& chunk : chunks)
        {
            bool ok;
            do
            {
                ok = cwd.GraphemeNext(state, chunk);
                widths.emplace_back(state.width);
            } while (ok);
        }
        // The final observed width must be 1 (VS15 narrowed the cluster).
        VERIFY_ARE_EQUAL(1, widths.back());

        // Astral-variant: U+1F5E1 (2-code-unit surrogate) split across a chunk boundary
        // from the trailing VS15.
        static constexpr std::array astral{
            std::wstring_view{ L"\U0001F5E1" },
            std::wstring_view{ L"\uFE0E" },
        };
        CodepointWidthDetector cwd2;
        cwd2.Reset(TextMeasurementMode::Graphemes);
        GraphemeState state2;
        std::vector<int> widths2;
        for (const auto& chunk : astral)
        {
            bool ok;
            do
            {
                ok = cwd2.GraphemeNext(state2, chunk);
                widths2.emplace_back(state2.width);
            } while (ok);
        }
        VERIFY_ARE_EQUAL(1, widths2.back());
    }

    TEST_METHOD(VS15PropertyCannotEnlarge)
    {
        // For every base codepoint with width >= 1, appending VS15 must never increase the width
        // and must never yield a negative width. Also asserts forward/reverse parity per sample,
        // which is the regression catcher for the cluster-base tracking parity bug.
        CodepointWidthDetector cwdPlain;
        cwdPlain.Reset(TextMeasurementMode::Graphemes);
        CodepointWidthDetector cwdVS;
        cwdVS.Reset(TextMeasurementMode::Graphemes);

        std::wstring buf;
        std::wstring bufVS;
        for (char32_t cp = 0x20; cp <= 0x10FFFF; ++cp)
        {
            // Skip surrogate halves.
            if (cp >= 0xD800 && cp <= 0xDFFF)
            {
                continue;
            }
            buf.clear();
            bufVS.clear();
            if (cp < 0x10000)
            {
                buf.push_back(static_cast<wchar_t>(cp));
            }
            else
            {
                const auto c = cp - 0x10000;
                buf.push_back(static_cast<wchar_t>(0xD800 | (c >> 10)));
                buf.push_back(static_cast<wchar_t>(0xDC00 | (c & 0x3FF)));
            }
            bufVS = buf;
            bufVS.push_back(L'\uFE0E');

            GraphemeState sPlain;
            cwdPlain.GraphemeNext(sPlain, buf);
            GraphemeState sVS;
            cwdVS.GraphemeNext(sVS, bufVS);

            if (sPlain.width >= 1)
            {
                const bool ok = sVS.width <= sPlain.width && sVS.width >= 0;
                if (!ok)
                {
                    WEX::Logging::Log::Error(
                        WEX::Common::String().Format(L"cp=U+%04X plain=%d vs15=%d",
                                                     static_cast<unsigned>(cp), sPlain.width, sVS.width));
                    VERIFY_IS_TRUE(ok);
                }
            }

            // Forward/reverse parity must hold for the VS15-suffixed sample, but only when
            // bufVS forms a single grapheme cluster (otherwise MeasureGraphemes{Forward,Reverse}
            // return the rightmost vs leftmost cluster's width respectively, which is not a
            // meaningful parity comparison). This is the property assertion that catches the
            // parity bug for clusters where the emoji base is not the cluster head (rainbow
            // flag + FE0E + ZWJ + emoji, Prepend + emoji + FE0E, etc.).
            if (sVS.len == static_cast<int>(bufVS.size()))
            {
                const auto fwd = MeasureGraphemesForward(bufVS);
                const auto rev = MeasureGraphemesReverse(bufVS);
                if (fwd.first != rev.first)
                {
                    WEX::Logging::Log::Error(
                        WEX::Common::String().Format(L"parity broken: cp=U+%04X fwd=%d rev=%d",
                                                     static_cast<unsigned>(cp), fwd.first, rev.first));
                    VERIFY_ARE_EQUAL(fwd.first, rev.first);
                }
            }
        }
    }

    TEST_METHOD(VS15ForwardReverseParityZwjEmoji)
    {
        // Rainbow flag with text-presentation request: WAVING WHITE FLAG (1F3F3, EPres=Y, wide)
        // + VS15 + ZWJ + RAINBOW (1F308, EPres=Y, wide). All four codepoints form a single
        // grapheme cluster (UAX#29 GB9/GB11). The VS15 requests text presentation for the
        // cluster's emoji base, so the entire cluster must collapse to width 1.
        //
        // Reasoning (independent of the production code direction):
        //   - The cluster contains an emoji-presentation base (the flag) targeted by FE0E.
        //   - Per the locked spec decision, FE0E never enlarges and caps at <= 1 when the
        //     cluster contains an emoji base.
        //   - Therefore the final cluster width must be 1, and forward must equal reverse.
        constexpr std::wstring_view input = L"\U0001F3F3\uFE0E\u200D\U0001F308";
        const auto fwd = MeasureGraphemesForward(input);
        const auto rev = MeasureGraphemesReverse(input);
        VERIFY_ARE_EQUAL(1, fwd.first);
        VERIFY_ARE_EQUAL(1, rev.first);
        VERIFY_ARE_EQUAL(fwd.first, rev.first);
        VERIFY_ARE_EQUAL(fwd.second, rev.second);
    }

    TEST_METHOD(VS15PrependBeforeEmojiBase)
    {
        // U+0600 ARABIC NUMBER SIGN (Prepend, narrow) + U+231A WATCH (EPres=Y, wide) + VS15.
        // UAX#29 GB9b joins the Prepend with what follows; GB9 joins the watch with VS15.
        // The cluster's emoji base is the watch (not the leftmost codepoint), so the FE0E cap
        // must still apply, and forward/reverse must agree.
        //
        // Reasoning: cluster contains an emoji-presentation base (231A) targeted by FE0E,
        // therefore width caps at 1 (overall narrow cluster).
        constexpr std::wstring_view input = L"\u0600\u231A\uFE0E";
        const auto fwd = MeasureGraphemesForward(input);
        const auto rev = MeasureGraphemesReverse(input);
        VERIFY_ARE_EQUAL(1, fwd.first);
        VERIFY_ARE_EQUAL(1, rev.first);
        VERIFY_ARE_EQUAL(fwd.first, rev.first);
        VERIFY_ARE_EQUAL(fwd.second, rev.second);
    }

    TEST_METHOD(VS15ZwjFlagSequence)
    {
        // Pin the rainbow-flag sequence's per-direction outcome explicitly. Same input as
        // VS15ForwardReverseParityZwjEmoji but the assertion focus is on each direction's
        // measured width independently, not just parity. The VS15 must narrow the entire
        // single-cluster ZWJ sequence to width 1.
        constexpr std::wstring_view input = L"\U0001F3F3\uFE0E\u200D\U0001F308";

        CodepointWidthDetector cwd;
        cwd.Reset(TextMeasurementMode::Graphemes);
        GraphemeState sFwd;
        bool more = true;
        int finalFwd = 0;
        while (more)
        {
            more = cwd.GraphemeNext(sFwd, input);
            finalFwd = sFwd.width;
        }
        VERIFY_ARE_EQUAL(1, finalFwd);

        CodepointWidthDetector cwd2;
        cwd2.Reset(TextMeasurementMode::Graphemes);
        GraphemeState sRev;
        more = true;
        int finalRev = 0;
        while (more)
        {
            more = cwd2.GraphemePrev(sRev, input);
            finalRev = sRev.width;
        }
        VERIFY_ARE_EQUAL(1, finalRev);
    }

    TEST_METHOD(VS15Keycap)
    {
        // Digit keycap with explicit text-presentation request:
        // '3' (Emoji=Y, default text, narrow) + VS15 + U+20E3 COMBINING ENCLOSING KEYCAP (Extend).
        // The cluster contains an emoji base targeted by FE0E, so it must collapse to width 1
        // in both directions.
        constexpr std::wstring_view input = L"3\uFE0E\u20E3";
        const auto fwd = MeasureGraphemesForward(input);
        const auto rev = MeasureGraphemesReverse(input);
        VERIFY_ARE_EQUAL(1, fwd.first);
        VERIFY_ARE_EQUAL(1, rev.first);
        VERIFY_ARE_EQUAL(fwd.first, rev.first);
    }

    TEST_METHOD(VS15ConsoleModeUnchanged)
    {
        // Console mode must be byte-for-byte identical with and without a trailing VS15.
        // VS15 only affects Graphemes-mode width; under Console the codepoint contributes
        // its trie width (0) and the per-call byte counts must match.
        const auto bytesFor = [](std::wstring_view s) {
            CodepointWidthDetector cwd;
            cwd.Reset(TextMeasurementMode::Console);
            GraphemeState state;
            int total = 0;
            for (;;)
            {
                const auto ok = cwd.GraphemeNext(state, s);
                total += state.len;
                if (!ok)
                {
                    break;
                }
            }
            return total;
        };
        const auto baseline = bytesFor(L"\u231A");
        const auto withVS15 = bytesFor(L"\u231A\uFE0E");
        // The base codepoint count is the same; FE0E adds one wchar of consumed input but the
        // width contribution is a no-op in Console mode (FE0E has trie width 0).
        VERIFY_ARE_EQUAL(baseline + 1, withVS15);

        // Verify width path: the per-cluster widths reported by Console mode are the trie widths
        // of the individual codepoints; FE0E's width is 0 and ⌚'s is unchanged.
        CodepointWidthDetector cwdNo;
        cwdNo.Reset(TextMeasurementMode::Console);
        GraphemeState sNo;
        cwdNo.GraphemeNext(sNo, std::wstring_view{ L"\u231A" });
        const auto noVSWatchWidth = sNo.width;

        CodepointWidthDetector cwdYes;
        cwdYes.Reset(TextMeasurementMode::Console);
        GraphemeState sYes;
        cwdYes.GraphemeNext(sYes, std::wstring_view{ L"\u231A\uFE0E" });
        const auto withVSWatchWidth = sYes.width;
        VERIFY_ARE_EQUAL(noVSWatchWidth, withVSWatchWidth);
    }

};
